<!doctype html>
<html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Tu restaurante | Adbana</title><link rel="icon" type="image/svg+xml" href="/images/adbana-logo.svg"><link rel="stylesheet" href="/css/panel.css"><script src="/js/panel.js"></script><script defer src="/js/alpine.min.js"></script></head>
<body><div x-data="panel" :data-theme="tema" class="app-root" x-cloak @keydown.escape.window="menuAbierto=false;perfilAbierto=false;avisosAbiertos=false">
<div class="auth-layout" x-show="!user"><aside class="auth-art"><a class="auth-brand" href="/"><img class="brand-logo" src="/images/adbana-logo.svg" alt="" width="30" height="40"> ADBANA</a><div><span class="eyebrow">CADA MESA. CADA PEDIDO.</span><h2>Todo listo para<br>un gran servicio<span>.</span></h2><p>Tu equipo conectado. Tu operación, bajo control.</p><div class="auth-illustration"><svg class="icon " aria-hidden="true"><use href="/images/panel-icons.svg#food"></use></svg><svg class="icon " aria-hidden="true"><use href="/images/panel-icons.svg#chef"></use></svg><svg class="icon " aria-hidden="true"><use href="/images/panel-icons.svg#bag"></use></svg></div></div><small>Hecho para el ritmo de tu restaurante.</small></aside><form class="login card" x-show="!user" @submit.prevent="login()">
<span class="eyebrow">BIENVENIDO A ADBANA</span><h1 x-text="registro ? 'Un nuevo comienzo.' : 'Qué bueno verte.'">Tu restaurante, en marcha</h1><p class="muted" x-text="registro ? 'Crea el espacio de trabajo de tu restaurante.' : 'Ingresa para continuar con tu servicio.'"></p>
<label x-show="registro">Nombre del restaurante<input x-model="restauranteNombre" :required="registro" maxlength="120"></label><label x-show="registro">Tu nombre<input x-model="nombre" :required="registro" maxlength="120"></label><label>Correo<input type="email" x-model="email" required autocomplete="username"></label><label>Contraseña<input type="password" x-model="password" :minlength="registro ? 8 : 1" required autocomplete="current-password"></label>
<p class="alert" x-show="error" x-text="error" role="alert"></p><button class="primary wide" :disabled="busy" x-text="registro ? 'Crear restaurante' : 'Ingresar'">Ingresar</button><button type="button" class="wide" @click="registro=!registro;error=''" x-text="registro ? 'Ya tengo cuenta' : 'Crear mi restaurante'"></button>
</form></div>
<template x-if="user"><div>
<div class="sidebar-backdrop" x-show="menuAbierto" @click="menuAbierto=false"></div>
<aside class="sidebar" :class="{'is-open':menuAbierto}" aria-label="Menú principal">
    <div class="restaurant-brand"><span class="brand-mark"><img class="brand-logo" src="/images/adbana-logo.svg" alt="" width="30" height="40"></span><strong x-text="user.restaurante?.nombre || 'Mi restaurante'"></strong><button class="mobile-only icon-button" aria-label="Cerrar menú" @click="menuAbierto=false"><svg class="icon " aria-hidden="true"><use href="/images/panel-icons.svg#close"></use></svg></button></div>
    <div class="workspace-caption">TU ESPACIO DE TRABAJO</div>
    <nav class="nav" aria-label="Secciones"><template x-for="item in navegacion" :key="item.id"><button :class="{active:tab===item.id}" :aria-current="tab===item.id?'page':null" :disabled="busy" @click="ir(item.id)"><span class="nav-icon"><svg class="icon" aria-hidden="true"><use :href="'/images/panel-icons.svg#'+item.icono"></use></svg></span><span x-text="item.nombre"></span></button></template></nav>
    <div class="sidebar-bottom"><a class="menu-link" :href="'/c/'+user.restaurante?.slug" target="_blank" rel="noopener"><svg class="icon " aria-hidden="true"><use href="/images/panel-icons.svg#external"></use></svg><span>Ver carta digital</span></a><button class="sidebar-user" @click="abrirPerfil()"><span class="avatar" x-text="iniciales"></span><span><strong x-text="user.name"></strong><small x-text="rolNombre"></small></span><svg class="icon " aria-hidden="true"><use href="/images/panel-icons.svg#chevron"></use></svg></button><small class="powered">Impulsado por <b>Adbana</b></small></div>
</aside>
<div class="workspace">
<header class="top">
    <button class="icon-button mobile-only" aria-label="Abrir menú" :aria-expanded="menuAbierto" @click="menuAbierto=true"><svg class="icon " aria-hidden="true"><use href="/images/panel-icons.svg#menu"></use></svg></button>
    <form class="global-search" @submit.prevent="buscarGlobal()"><svg class="icon " aria-hidden="true"><use href="/images/panel-icons.svg#search"></use></svg><input aria-label="Buscar en la operación" x-model="busquedaGlobal" :placeholder="user.rol==='cocina'?'Buscar una comanda…':'Buscar productos…'"><kbd>↵</kbd></form>
    <div class="top-actions"><span class="today-date" x-text="new Date().toLocaleDateString('es-PE',{day:'numeric',month:'short',year:'numeric'})"></span><button class="icon-button" aria-label="Actualizar sección" title="Actualizar" :disabled="busy" @click="accion(()=>actualizar())" :class="{'is-loading':busy || cargando}"><svg class="icon " aria-hidden="true"><use href="/images/panel-icons.svg#refresh"></use></svg></button>
    <div class="popover-anchor" @click.outside="avisosAbiertos=false"><button class="icon-button" aria-label="Avisos operativos" :aria-expanded="avisosAbiertos" @click="verAvisos()"><svg class="icon " aria-hidden="true"><use href="/images/panel-icons.svg#bell"></use></svg><span class="notification-dot" x-show="notificaciones.length"></span></button><div class="popover notifications" x-show="avisosAbiertos"><div class="popover-heading"><strong>Avisos operativos</strong><small>Estado actual</small></div><p class="muted" x-show="busy">Consultando tu operación…</p><p class="empty-copy" x-show="!busy && !notificaciones.length">No hay avisos por ahora.</p><template x-for="n in notificaciones" :key="n.id"><button class="notification-item" @click="ir(n.destino)"><svg class="icon"><use :href="'/images/panel-icons.svg#'+n.icono"></use></svg><span><strong x-text="n.titulo"></strong><small x-text="n.texto"></small></span><svg class="icon " aria-hidden="true"><use href="/images/panel-icons.svg#arrow"></use></svg></button></template></div></div>
    <button class="icon-button" :aria-label="tema==='light'?'Activar tema oscuro':'Activar tema claro'" @click="cambiarTema()"><svg class="icon"><use :href="'/images/panel-icons.svg#'+(tema==='light'?'moon':'sun')"></use></svg></button>
    <div class="popover-anchor" @click.outside="perfilAbierto=false"><button class="profile-trigger" :aria-label="'Abrir perfil de '+user.name" :aria-expanded="perfilAbierto" @click="perfilAbierto=!perfilAbierto;avisosAbiertos=false"><span class="avatar" x-text="iniciales"></span><span class="profile-label"><strong x-text="user.name"></strong><small x-text="rolNombre"></small></span><svg class="icon " aria-hidden="true"><use href="/images/panel-icons.svg#chevron"></use></svg></button><div class="popover profile-popover" x-show="perfilAbierto"><strong x-text="user.name"></strong><small x-text="user.email"></small><button @click="abrirPerfil()"><svg class="icon " aria-hidden="true"><use href="/images/panel-icons.svg#user"></use></svg> Mi perfil</button><button @click="logout()" :disabled="busy"><svg class="icon " aria-hidden="true"><use href="/images/panel-icons.svg#logout"></use></svg> Cerrar sesión</button></div></div></div>
</header>
<main class="shell"><div class="page-heading"><div><div class="breadcrumb">Mi restaurante <span>/</span> <span x-text="tituloSeccion"></span></div><h1 x-text="tab==='inicio'?'Hola, '+user.name.split(' ')[0]:tituloSeccion"></h1><p class="muted" x-text="tab==='inicio'?'Una mirada a tu negocio. Todo en su lugar.':'Tu servicio, paso a paso.'"></p></div><span class="update-time" x-show="ultimaActualizacion">Actualizado <b x-text="ultimaActualizacion"></b></span></div>
<p class="section-loading" x-show="cargando" role="status"><span class="loading-dot"></span>Actualizando datos de esta sección…</p><p class="alert" role="alert" x-show="error" x-text="error"></p><p class="alert success" role="status" x-show="aviso" x-text="aviso"></p>

<section x-show="tab==='inicio'" class="dashboard-section">
<div class="dashboard-loading" x-show="(busy || cargando) && !dashboard" role="status">Preparando el resumen de tu restaurante…</div><template x-if="dashboard"><div>
    <div class="stats-grid">
        <article class="stat-card"><span class="stat-icon red"><svg class="icon " aria-hidden="true"><use href="/images/panel-icons.svg#wallet"></use></svg></span><span>Ventas cobradas hoy</span><strong x-text="money(dashboard.ventas_hoy)"></strong><small x-text="dashboard.cobrados_hoy+' '+(dashboard.cobrados_hoy===1?'cobro registrado':'cobros registrados')"></small></article>
        <article class="stat-card"><span class="stat-icon blue"><svg class="icon " aria-hidden="true"><use href="/images/panel-icons.svg#bag"></use></svg></span><span>Pedidos del día</span><strong x-text="dashboard.pedidos_hoy"></strong><small>Registrados hoy</small></article>
        <article class="stat-card"><span class="stat-icon orange"><svg class="icon " aria-hidden="true"><use href="/images/panel-icons.svg#chef"></use></svg></span><span>En operación</span><strong x-text="dashboard.abiertos"></strong><small>Pedidos sin finalizar</small></article>
        <article class="stat-card"><span class="stat-icon purple"><svg class="icon " aria-hidden="true"><use href="/images/panel-icons.svg#chart"></use></svg></span><span>Ticket promedio</span><strong x-text="money(dashboard.ticket_promedio)"></strong><small>Por pedido cobrado hoy</small></article>
    </div>
    <div class="dashboard-grid"><article class="card sales-chart"><div class="card-heading"><div><h2>Así van tus ventas</h2><p class="muted">Cobros de los últimos 7 días</p></div><span class="range-chip">Últimos 7 días</span></div><strong class="chart-total" x-text="money(dashboard.ventas_semana)"></strong><div class="chart-container"><svg viewBox="0 0 610 195" role="img" aria-label="Gráfico de cobros de los últimos siete días"><defs><linearGradient id="sales-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#ee493b" stop-opacity=".25"/><stop offset="100%" stop-color="#ee493b" stop-opacity="0"/></linearGradient></defs><path d="M35 30H575 M35 72H575 M35 113H575 M35 155H575" class="chart-grid"/><path :d="grafico.area" fill="url(#sales-fill)"/><polyline :points="grafico.linea" fill="none" stroke="#ef4b3e" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/><g><circle :cx="grafico.puntos[0]?.x || 0" :cy="grafico.puntos[0]?.y || 155" r="4" fill="#ef4b3e" stroke="var(--card)" stroke-width="2"><title x-text="grafico.puntos[0] ? grafico.puntos[0].fecha+': '+money(grafico.puntos[0].valor) : ''"></title></circle><text x="35" y="184" text-anchor="middle" x-text="dashboard.serie[0] ? fechaCorta(dashboard.serie[0].fecha) : ''"></text></g><g><circle :cx="grafico.puntos[1]?.x || 0" :cy="grafico.puntos[1]?.y || 155" r="4" fill="#ef4b3e" stroke="var(--card)" stroke-width="2"><title x-text="grafico.puntos[1] ? grafico.puntos[1].fecha+': '+money(grafico.puntos[1].valor) : ''"></title></circle><text x="125" y="184" text-anchor="middle" x-text="dashboard.serie[1] ? fechaCorta(dashboard.serie[1].fecha) : ''"></text></g><g><circle :cx="grafico.puntos[2]?.x || 0" :cy="grafico.puntos[2]?.y || 155" r="4" fill="#ef4b3e" stroke="var(--card)" stroke-width="2"><title x-text="grafico.puntos[2] ? grafico.puntos[2].fecha+': '+money(grafico.puntos[2].valor) : ''"></title></circle><text x="215" y="184" text-anchor="middle" x-text="dashboard.serie[2] ? fechaCorta(dashboard.serie[2].fecha) : ''"></text></g><g><circle :cx="grafico.puntos[3]?.x || 0" :cy="grafico.puntos[3]?.y || 155" r="4" fill="#ef4b3e" stroke="var(--card)" stroke-width="2"><title x-text="grafico.puntos[3] ? grafico.puntos[3].fecha+': '+money(grafico.puntos[3].valor) : ''"></title></circle><text x="305" y="184" text-anchor="middle" x-text="dashboard.serie[3] ? fechaCorta(dashboard.serie[3].fecha) : ''"></text></g><g><circle :cx="grafico.puntos[4]?.x || 0" :cy="grafico.puntos[4]?.y || 155" r="4" fill="#ef4b3e" stroke="var(--card)" stroke-width="2"><title x-text="grafico.puntos[4] ? grafico.puntos[4].fecha+': '+money(grafico.puntos[4].valor) : ''"></title></circle><text x="395" y="184" text-anchor="middle" x-text="dashboard.serie[4] ? fechaCorta(dashboard.serie[4].fecha) : ''"></text></g><g><circle :cx="grafico.puntos[5]?.x || 0" :cy="grafico.puntos[5]?.y || 155" r="4" fill="#ef4b3e" stroke="var(--card)" stroke-width="2"><title x-text="grafico.puntos[5] ? grafico.puntos[5].fecha+': '+money(grafico.puntos[5].valor) : ''"></title></circle><text x="485" y="184" text-anchor="middle" x-text="dashboard.serie[5] ? fechaCorta(dashboard.serie[5].fecha) : ''"></text></g><g><circle :cx="grafico.puntos[6]?.x || 0" :cy="grafico.puntos[6]?.y || 155" r="4" fill="#ef4b3e" stroke="var(--card)" stroke-width="2"><title x-text="grafico.puntos[6] ? grafico.puntos[6].fecha+': '+money(grafico.puntos[6].valor) : ''"></title></circle><text x="575" y="184" text-anchor="middle" x-text="dashboard.serie[6] ? fechaCorta(dashboard.serie[6].fecha) : ''"></text></g></svg><p class="chart-empty" x-show="!grafico.hayVentas">Aquí verás tus ventas cuando registres el primer cobro.</p></div></article>
    <article class="card top-products"><div class="card-heading"><div><h2>Los favoritos</h2><p class="muted">Productos más vendidos · 7 días</p></div><svg class="icon " aria-hidden="true"><use href="/images/panel-icons.svg#food"></use></svg></div><div class="empty-state compact" x-show="!dashboard.top.length"><svg class="icon " aria-hidden="true"><use href="/images/panel-icons.svg#bag"></use></svg><h3>Tu próximo favorito está por llegar</h3><p>Los productos aparecerán aquí al registrar ventas.</p></div><template x-for="(p,i) in dashboard.top" :key="p.nombre"><div class="rank-item"><span class="rank-number" x-text="String(i+1).padStart(2,'0')"></span><div><strong x-text="p.nombre"></strong><small x-text="p.cantidad+' '+(Number(p.cantidad)===1?'unidad':'unidades')"></small><div class="rank-track"><span :style="'width:'+Math.max(4,Number(p.cantidad)/Number(dashboard.top[0].cantidad)*100)+'%'"></span></div></div><b x-text="money(p.ventas)"></b></div></template></article>
    <article class="card recent-orders"><div class="card-heading"><div><h2>Últimos pedidos</h2><p class="muted">Lo más reciente de tu restaurante</p></div><button class="text-button" @click="ir('pedidos')">Ver pedidos <svg class="icon " aria-hidden="true"><use href="/images/panel-icons.svg#arrow"></use></svg></button></div><div class="table-scroll"><table><thead><tr><th>Pedido</th><th>Cliente</th><th>Atención</th><th>Estado</th><th>Total</th></tr></thead><tbody><template x-for="p in dashboard.recientes" :key="p.id"><tr><td><b x-text="'#'+p.id"></b></td><td x-text="p.cliente_nombre"></td><td x-text="p.tipo"></td><td><span class="pill" :data-status="p.estado" x-text="p.estado"></span><small x-show="p.cobrado_at" class="paid-label">Pagado</small></td><td><strong x-text="money(p.total)"></strong></td></tr></template></tbody></table><p class="empty-copy" x-show="!dashboard.recientes.length">Todo listo para tu primer pedido.</p></div></article>
    <article class="service-card"><span class="stat-icon"><img class="brand-logo" src="/images/adbana-logo.svg" alt="" width="30" height="40"></span><h2>El próximo gran servicio<br>empieza aquí.</h2><p>Tu carta, tu equipo y tus pedidos.<br>Un solo espacio para trabajar mejor.</p><button @click="ir('venta')">Comenzar una venta <svg class="icon " aria-hidden="true"><use href="/images/panel-icons.svg#arrow"></use></svg></button><div class="service-orbit" aria-hidden="true"><svg class="icon " aria-hidden="true"><use href="/images/panel-icons.svg#food"></use></svg></div></article></div>
</div></template></section>
<section x-show="tab==='perfil'" class="profile-layout"><article class="card profile-summary"><span class="avatar large" x-text="iniciales"></span><h2 x-text="user.name"></h2><span class="pill" x-text="rolNombre"></span><p class="muted" x-text="user.restaurante?.nombre"></p><div class="sep"></div><p>Un perfil para tu trabajo diario.<br>Tu rol lo administra el restaurante.</p></article><form class="card" @submit.prevent="guardarPerfil()"><h2>Tu información</h2><p class="muted">Mantén tus datos al día.</p><label>Nombre<input x-model="perfil.name" maxlength="120" autocomplete="name" required></label><label>Correo<input type="email" x-model="perfil.email" autocomplete="email" required></label><div class="sep"></div><h3>Seguridad de tu cuenta</h3><p class="muted">Para cambiar el correo o la contraseña, confirma tu contraseña actual.</p><label>Contraseña actual<input type="password" x-model="perfil.current_password" autocomplete="current-password"></label><div class="form-grid"><label>Nueva contraseña<input type="password" x-model="perfil.password" minlength="8" autocomplete="new-password"></label><label>Confirmar nueva contraseña<input type="password" x-model="perfil.password_confirmation" minlength="8" autocomplete="new-password"></label></div><button class="primary" :disabled="cargando || (busy)">Guardar cambios</button></form></section>
<section x-show="tab==='venta'" class="cols pos-layout"><div class="card catalog-card"><h2>Punto de venta</h2><form class="row" @submit.prevent="pagina=1;accion(()=>actualizar())"><input aria-label="Buscar productos" x-model="q" placeholder="Busca una bebida o un plato"><button>Buscar</button></form>
<div class="empty-state" x-show="!productos.length"><svg class="icon " aria-hidden="true"><use href="/images/panel-icons.svg#food"></use></svg><h3>Tu carta empieza aquí</h3><p>No hay productos para mostrar con esta búsqueda.</p><button class="primary" x-show="user.permisos.productos" @click="ir('productos')">Agregar productos</button></div><div class="grid product-grid"><template x-for="p in productos" :key="p.id"><button class="product" :disabled="cargando || (busy || !p.activo || p.stock<1)" @click="agregar(p)"><span class="product-visual"><template x-if="p.imagen"><img :src="p.imagen" alt="" loading="lazy"></template><span x-show="!p.imagen"><svg class="icon " aria-hidden="true"><use href="/images/panel-icons.svg#food"></use></svg></span><span class="product-add">+</span></span><strong x-text="p.nombre"></strong><span class="product-price" x-text="money(p.precio)"></span><small x-text="p.activo ? 'Stock: '+p.stock : 'Inactivo'"></small></button></template></div>
<div class="row"><button :disabled="cargando || (pagina<=1 || busy)" @click="pagina--;accion(()=>actualizar())">Anterior</button><small x-text="pagina+' / '+ultima"></small><button :disabled="cargando || (pagina>=ultima || busy)" @click="pagina++;accion(()=>actualizar())">Siguiente</button></div></div>
<div class="card cart-card"><div class="card-heading"><h2>Pedido actual</h2><span class="count-chip" x-text="lineas.length+' productos'"></span></div><p x-show="!lineas.length" class="muted">Selecciona productos para comenzar.</p><template x-for="p in lineas" :key="p.id"><div class="row"><span x-text="p.nombre"></span><div class="actions"><button :disabled="cargando || (busy)" @click="quitar(p)" :aria-label="'Quitar '+p.nombre">−</button><span x-text="p.cantidad"></span><button :disabled="cargando || (busy)" @click="agregar(p)" :aria-label="'Agregar '+p.nombre">+</button></div><strong x-text="money(p.precio*p.cantidad)"></strong></div></template>
<div class="sep"></div><div class="row"><strong>Total</strong><span class="tot" x-text="money(total)"></span></div>
<label>Cliente<input x-model="cliente" maxlength="120" :disabled="cargando || (busy)"></label><label>Atención<select x-model="tipo" :disabled="cargando || (busy)"><option value="recojo">Mostrador / para llevar</option><option value="mesa">En mesa</option><option value="delivery">Delivery</option></select></label>
<label x-show="tipo==='mesa'">Mesa<input x-model="mesa" maxlength="20" :disabled="cargando || (busy)"></label><label x-show="tipo==='delivery'">Dirección<input x-model="direccion" maxlength="255" :disabled="cargando || (busy)"></label><label x-show="tipo==='delivery'">Teléfono<input x-model="telefono" maxlength="30" :disabled="cargando || (busy)"></label><label>Notas<textarea x-model="notas" maxlength="500" :disabled="cargando || (busy)"></textarea></label>
<button x-show="user.permisos.caja" class="primary wide" :disabled="cargando || (busy || !lineas.length || !caja)" @click="guardarVenta(true)">Registrar y cobrar</button><button class="wide" :disabled="cargando || (busy || !lineas.length)" @click="guardarVenta(false)">Enviar pedido a cocina</button><p class="muted" x-show="user.permisos.caja && !caja">Abre tu turno en «Mi caja» para cobrar.</p></div></section>

<section x-show="['pedidos','cocina'].includes(tab)"><h1 x-text="tab==='cocina'?'Comandas de cocina':'Pedidos abiertos'"></h1><p class="muted">Se actualizan cada 15 segundos. Cobro y entrega se registran por separado.</p><div class="empty-state" x-show="!pedidosVisibles.length"><svg class="icon " aria-hidden="true"><use href="/images/panel-icons.svg#check"></use></svg><h3>Todo al día</h3><p>No hay pedidos que coincidan con esta vista.</p></div><div class="grid orders-grid"><template x-for="p in pedidosVisibles" :key="p.id"><article class="card order"><div class="row"><h2 x-text="'#'+p.id"></h2><span class="pill" :data-status="p.estado" x-text="p.estado"></span></div><strong x-text="p.cliente_nombre"></strong><p x-text="p.tipo + (p.mesa?' · Mesa '+p.mesa:'')"></p><small x-text="new Date(p.created_at).toLocaleString()"></small><template x-for="d in p.detalles" :key="d.id"><p x-text="d.cantidad+' × '+d.nombre_producto"></p></template><p x-show="p.notas" x-text="p.notas"></p><p x-show="p.direccion" x-text="p.direccion"></p><strong x-show="tab!=='cocina' && user.permisos.caja" x-text="money(p.total)"></strong><p class="pill" x-show="p.cobrado_at">Pagado · entrega independiente</p><button class="primary wide" x-show="siguiente(p)" :disabled="cargando || (busy)" @click="estado(p,siguiente(p))" x-text="'Pasar a '+siguiente(p)"></button><button class="wide" x-show="tab!=='cocina' && user.permisos.caja && !p.cobrado_at" :disabled="cargando || (busy || !caja)" @click="prepararCobro(p)">Cobrar pedido</button><button class="wide" x-show="tab!=='cocina' && user.permisos.cancelar && !p.cobrado_at" :disabled="cargando || (busy)" @click="estado(p,'cancelado')">Cancelar pedido</button></article></template></div></section>

<section x-show="tab==='mesas'"><h1>Mesas con pedidos abiertos</h1><p class="muted">Las mesas se identifican al registrar el pedido. Esta vista reúne sus pedidos activos.</p><p x-show="!mesas.length">No hay mesas con pedidos abiertos.</p><div class="grid"><template x-for="m in mesas" :key="m.nombre"><article class="card"><h2 x-text="'Mesa '+m.nombre"></h2><strong x-text="'Total pendiente: '+money(m.pedidos.reduce((s,p)=>s+(p.cobrado_at?0:Number(p.total)),0))"></strong><template x-for="p in m.pedidos" :key="p.id"><div><p x-text="'#'+p.id+' · '+p.estado+' · '+money(p.total)"></p><button x-show="user.permisos.caja && !p.cobrado_at" :disabled="cargando || (!caja || busy)" @click="prepararCobro(p)">Cobrar pedido</button></div></template></article></template></div></section>

<section x-show="tab==='caja'" class="cols"><div class="card"><h1>Mi turno de caja</h1><p class="muted">Los cobros quedan a tu nombre. El efectivo permanece bajo tu responsabilidad hasta rendirlo; cerrar el turno no transfiere dinero a otro cajero.</p><form x-show="!caja && !cargando" @submit.prevent="abrirCaja()"><label>Efectivo inicial (S/)<input type="number" min="0" step=".01" x-model="inicial" required></label><button class="primary" :disabled="cargando || (busy)">Abrir caja</button></form>
<template x-if="caja"><div><p x-text="'Turno #'+caja.id+' · abierto '+new Date(caja.created_at).toLocaleString()"></p><div class="row"><span>Fondo inicial</span><strong x-text="money(caja.saldo_inicial)"></strong></div><template x-for="(valor,medio) in resumen?.ventas_por_medio || {}" :key="medio"><div class="row"><span x-text="'Ventas '+medio"></span><strong x-text="money(valor)"></strong></div></template><div class="row"><span>Entradas</span><span x-text="money(resumen?.entradas)"></span></div><div class="row"><span>Salidas</span><span x-text="money(resumen?.salidas)"></span></div><div class="row"><strong>Efectivo esperado</strong><strong x-text="money(resumen?.efectivo_esperado)"></strong></div><form @submit.prevent="cerrarCaja()"><label>Efectivo contado (S/)<input type="number" min="0" step=".01" x-model="contado" required></label><button class="primary" :disabled="cargando || (busy)">Cerrar y registrar diferencia</button></form></div></template>
<template x-if="cierre"><div class="alert success"><h2>Turno cerrado</h2><p x-text="'Esperado: '+money(cierre.efectivo_esperado)"></p><p x-text="'Contado: '+money(cierre.efectivo_contado)"></p><strong x-text="'Diferencia: '+money(cierre.diferencia)"></strong></div></template></div>
<form class="card" x-show="caja" @submit.prevent="moverCaja()"><h2>Movimiento de efectivo</h2><label>Tipo<select x-model="movimiento.tipo"><option value="entrada">Entrada</option><option value="salida">Salida</option></select></label><label>Monto<input type="number" min=".01" step=".01" x-model="movimiento.monto" required></label><label>Motivo<input x-model="movimiento.motivo" maxlength="255" required></label><button class="primary" :disabled="cargando || (busy)">Registrar movimiento</button><p class="muted">Los movimientos de efectivo y los gastos contables se registran por separado.</p></form></section>

<div>
<section x-show="tab==='productos' && (user.permisos.productos || user.permisos.stock)" class="cols"><div class="card"><h1>Productos</h1><form x-show="user.permisos.productos" @submit.prevent="guardarProducto()"><label>Nombre<input x-model="producto.nombre" maxlength="150" required></label><div class="row"><label>Precio de venta<input type="number" min="0" step=".01" x-model="producto.precio" required></label><label>Costo<input type="number" min="0" step=".01" x-model="producto.costo" required></label></div><label>Categoría<select x-model="producto.categoria_id"><option value="">Sin categoría</option><template x-for="c in categorias" :key="c.id"><option :value="c.id" x-text="c.nombre"></option></template></select></label><p class="muted">Registra cada presentación como producto: por ejemplo, «Caja de cerveza», precio por caja y stock en cajas. No comparte stock con botellas individuales.</p><label x-show="!producto.id">Stock inicial<input type="number" min="0" step="1" x-model="producto.stock"></label><label>Stock mínimo<input type="number" min="0" step="1" x-model="producto.stock_minimo"></label><label><input type="checkbox" x-model="producto.activo" style="width:auto"> Disponible para venta</label><button class="primary" :disabled="cargando || (busy)">Guardar producto</button></form><div class="sep"></div><template x-for="p in productos" :key="p.id"><div class="row"><span x-text="p.nombre+' · '+money(p.precio)+' · stock '+p.stock"></span><button x-show="user.permisos.productos" @click="editar(p)">Editar</button></div></template><div class="actions"><button :disabled="cargando || (pagina<=1 || busy)" @click="pagina--;accion(()=>actualizar())">Anterior</button><button :disabled="cargando || (pagina>=ultima || busy)" @click="pagina++;accion(()=>actualizar())">Siguiente</button></div></div>
<div class="list"><form class="card" x-show="user.permisos.productos" @submit.prevent="guardarCategoria()"><h2>Nueva categoría</h2><label>Nombre<input x-model="categoriaNombre" required maxlength="100"></label><button :disabled="cargando || (busy)">Crear categoría</button></form><form class="card" x-show="user.permisos.stock" @submit.prevent="moverStock()"><h2>Ajustar inventario</h2><label>Producto<select x-model="stockForm.producto_id" required><option value="">Selecciona</option><template x-for="p in productos" :key="p.id"><option :value="p.id" x-text="p.nombre"></option></template></select></label><label>Movimiento<select x-model="stockForm.tipo"><option value="entrada">Entrada de mercadería</option><option value="salida">Salida / merma</option><option value="ajuste">Conteo físico</option></select></label><label x-show="stockForm.tipo!=='ajuste'">Cantidad<input type="number" min="1" step="1" x-model="stockForm.cantidad"></label><label x-show="stockForm.tipo==='ajuste'">Stock contado<input type="number" min="0" step="1" x-model="stockForm.stock_real"></label><label>Motivo<input x-model="stockForm.motivo" required maxlength="255"></label><button class="primary" :disabled="cargando || (busy)">Registrar</button></form></div></section>
<section x-show="tab==='ventas'" class="cols"><div class="card" x-show="user.permisos.reportes"><h1>Ventas del día</h1><form class="row" @submit.prevent="verReporte()"><input type="date" aria-label="Fecha del reporte" x-model="fecha" required><button :disabled="cargando || (busy)">Consultar</button></form><template x-if="reporte"><div><template x-for="k in ['ventas','costo_vendido','ganancia_bruta','gastos','ganancia_neta']" :key="k"><div class="row"><span x-text="k.replaceAll('_',' ')"></span><strong x-text="money(reporte[k])"></strong></div></template><p x-text="reporte.pedidos_cobrados+' pedidos cobrados'"></p><h2>Más vendidos</h2><template x-for="(p,n) in reporte.top_productos" :key="n"><p x-text="p.producto+' · '+p.cantidad+' unidades'"></p></template></div></template></div><form class="card" x-show="user.permisos.gastos" @submit.prevent="guardarGasto()"><h2>Registrar gasto</h2><label>Descripción<input x-model="gasto.descripcion" required maxlength="255"></label><label>Monto<input type="number" min=".01" step=".01" x-model="gasto.monto" required></label><label>Categoría<input x-model="gasto.categoria" maxlength="50"></label><button class="primary" :disabled="cargando || (busy)">Guardar gasto</button></form></section>
<section x-show="tab==='equipo' && user.permisos.equipo" class="cols team-section">
<div class="card"><h1>Equipo y permisos</h1><p class="muted">Cada rol incluye funciones iniciales. Puedes adaptar los permisos de cada persona sin cambiar su puesto.</p>
<template x-for="u in usuarios" :key="u.id"><article class="team-member"><div><strong x-text="u.name"></strong><small x-text="nombreRol(u.rol)+' · '+(u.activo?'Activo':'Desactivado')"></small><small x-show="Object.keys(u.permisos_personalizados||{}).length">Permisos personalizados</small></div><div class="actions"><button x-show="u.editable" :disabled="busy || cargando" @click="editarPermisos(u)">Permisos</button><button x-show="u.editable" :disabled="busy || cargando" @click="activarUsuario(u)" x-text="u.activo?'Desactivar':'Activar'"></button><span class="muted" x-show="!u.editable" x-text="u.id===user.id?'Tu cuenta':u.rol==='dueno'?'Acceso del dueño':'Gestionado por el dueño'"></span></div></article></template></div>
<form class="card" x-show="!editandoUsuario" @submit.prevent="crearUsuario()"><h2>Nuevo integrante</h2><label>Rol inicial<select x-model="nuevoUsuario.rol"><template x-for="rol in rolesDisponibles" :key="rol"><option :value="rol" x-text="nombreRol(rol)"></option></template></select></label><p class="muted">Después de crearlo, usa «Permisos» para añadir o quitar funciones. Por ejemplo, permitir que un mesero cobre.</p><label>Nombre<input x-model="nuevoUsuario.name" required maxlength="120"></label><label>Correo<input type="email" x-model="nuevoUsuario.email" required></label><label>Contraseña<input type="password" x-model="nuevoUsuario.password" minlength="8" required autocomplete="new-password"></label><button class="primary" :disabled="busy || cargando || !rolesDisponibles.length">Crear integrante</button></form>
<form class="card permission-editor" x-show="editandoUsuario" @submit.prevent="guardarPermisos()"><h2 x-text="'Permisos de '+(editandoUsuario?.name||'')"></h2><p class="muted" x-text="'Rol base: '+nombreRol(editandoUsuario?.rol)"></p><p>Activa las funciones que esta persona necesita. Desmarca las que no debe utilizar.</p>
<template x-for="grupo in ['Operación','Administración']" :key="grupo"><fieldset><legend x-text="grupo"></legend><template x-for="[clave,opcion] in Object.entries(catalogoPermisos?.permisos||{}).filter(([,p])=>p.grupo===grupo)" :key="clave"><label class="permission-option"><input type="checkbox" x-model="permisosEditados[clave]" :disabled="busy || cargando || !catalogoPermisos.delegables.includes(clave)"><span><strong x-text="opcion.nombre"></strong><small x-text="opcion.descripcion"></small><small class="permission-default" x-text="!catalogoPermisos.delegables.includes(clave)?'Solo puede modificarlo un responsable autorizado':catalogoPermisos.roles[editandoUsuario?.rol]?.[clave]?'Incluido en el rol base':'Adicional al rol base'"></small></span></label></template></fieldset></template>
<p class="muted">No puedes cambiar tus propios permisos. Un turno de caja abierto debe cerrarse antes de retirar el acceso o desactivar la cuenta.</p><div class="actions"><button class="primary" :disabled="busy || cargando">Guardar permisos</button><button type="button" :disabled="busy || cargando" @click="editandoUsuario=null">Volver</button><button type="button" :disabled="busy || cargando" @click="restaurarPermisos()">Restablecer rol base</button></div></form>
</section>
</div>
</main></div></div></template>
<div class="modal" x-show="cobro" role="dialog" aria-modal="true" aria-label="Cobrar pedido"><form class="card dialog" @submit.prevent="pagar()"><h2 x-text="'Cobrar pedido #'+cobro?.id"></h2><p class="tot" x-text="money(cobro?.total)"></p><label>Medio de pago<select x-model="medio"><option value="efectivo">Efectivo</option><option value="yape">Yape</option><option value="plin">Plin</option><option value="tarjeta">Tarjeta</option></select></label><label x-show="medio==='efectivo'">Efectivo recibido<input type="number" min="0" step=".01" x-model="recibido"></label><p x-show="medio==='efectivo'" x-text="'Vuelto: '+money(Math.max(0,vuelto))"></p><p class="alert" x-show="error" x-text="error"></p><p class="muted">Para pagos digitales, verifica la recepción en tu cuenta antes de confirmar.</p><button class="primary wide" :disabled="cargando || (busy || !caja || (medio==='efectivo' && vuelto<0))">Confirmar cobro</button><button type="button" class="wide" :disabled="cargando || (busy)" @click="cobro=null">Volver</button></form></div>
<div class="modal" x-show="comprobante" role="dialog" aria-modal="true" aria-label="Constancia de venta"><div class="card dialog receipt"><h2 x-text="user?.restaurante?.nombre"></h2><p>Constancia interna de venta</p><p x-text="'Pedido #'+comprobante?.id"></p><p x-text="comprobante?.cliente_nombre"></p><template x-for="d in comprobante?.detalles || []" :key="d.id"><div class="row"><span x-text="d.cantidad+' × '+d.nombre_producto"></span><span x-text="money(d.subtotal)"></span></div></template><div class="sep"></div><p x-text="'Total: '+money(comprobante?.total)"></p><p x-text="'Pago: '+comprobante?.medio_pago"></p><p x-text="'Recibido: '+money(comprobante?.recibido)"></p><p x-text="'Vuelto: '+money(comprobante?.vuelto)"></p><small>No es comprobante de pago electrónico SUNAT.</small><button class="primary wide" @click="imprimir()">Imprimir</button><button class="wide" @click="comprobante=null">Cerrar</button></div></div>
</div></body></html>
